<div class="grid"><section class="card"><h2>Personal & contact details</h2><dl class="hr-details"><?php foreach(['name'=>'Full name','preferred'=>'Preferred name','email'=>'Email','phone'=>'Phone','dob'=>'Date of birth','address'=>'Address','contact_name'=>'Emergency contact','relationship'=>'Relationship','contact_phone'=>'Emergency phone','notes'=>'Contact notes'] as $key=>$label):?><dt><?=access_h($label)?></dt><dd><?=access_h($key==='dob'?display_date($data[$key] ?? ''):($data[$key] ?? ''))?:'—'?></dd><?php endforeach?></dl></section><section class="card"><h2>Onboarding checklist</h2><?php foreach(['contract'=>'Signed employment contract','identity'=>'Identity verified','sop'=>'SOP orientation','safety'=>'Safety briefing','training'=>'Role training'] as $key=>$label):?><div class="hr-row"><span><?=access_h($label)?></span><span class="hr-badge"><?=!empty($data[$key])?'Complete':'Outstanding'?></span></div><?php endforeach?></section></div>
<section class="card"><h2>Issued items & handover</h2><?php foreach($snapshot['items'] as $item):?><div class="hr-row"><span><?=access_h($item['name'] ?? $item['item_name'] ?? '')?></span><span><?=!empty($item['returned_at'])?'Returned':'Issued'?></span><?php if(empty($item['returned_at'])&&$can('hr.manage')):?><form method="post"><?php hr_fields('return_item',$id,$version);?><input type="hidden" name="item_id" value="<?=(int)$item['id']?>"><?php hr_reason();?><button>Record return</button></form><?php endif?></div><?php endforeach?><?php if(!$snapshot['items']):?><p class="muted">No issued items recorded.</p><?php endif?><?php if($hrCanIssueItem):?><details><summary>Issue an item</summary><form method="post"><?php hr_fields('issue_item',$id,$version);hr_input('Item name','name','', 'text',true);hr_reason();?><button>Record issued item</button></form></details><?php endif?></section>
